<?php

namespace App\Domain\System;

use App\Support\Canonical;
use Illuminate\Support\Facades\File;
use Symfony\Component\Process\Process;

/**
 * Production builds ship release-manifest.json generated by the release pipeline
 * (php artisan system:manifest). Without it the app reports a dev version.
 */
class ReleaseManifest
{
    /** @var array<string, mixed>|null */
    private ?array $built = null;

    private bool $loaded = false;

    private string|false|null $sha = false;

    public function path(): string
    {
        return base_path('release-manifest.json');
    }

    /** @return array<string, mixed>|null */
    public function built(): ?array
    {
        if (! $this->loaded) {
            $this->loaded = true;
            $path = $this->path();
            $this->built = File::exists($path) ? json_decode(File::get($path), true) : null;
        }

        return $this->built;
    }

    public function isTagged(): bool
    {
        return $this->built() !== null;
    }

    public function version(): string
    {
        if ($built = $this->built()) {
            return $built['app_version'];
        }

        $base = File::exists(base_path('VERSION')) ? trim(File::get(base_path('VERSION'))) : '0.0.0';

        return "{$base}-dev+".($this->gitSha() ?? 'local');
    }

    public function gitSha(): ?string
    {
        if ($built = $this->built()) {
            return $built['git_sha'] ?? null;
        }

        if ($this->sha === false) {
            $process = new Process(['git', 'rev-parse', '--short', 'HEAD'], base_path());
            $process->run();
            $this->sha = $process->isSuccessful() ? trim($process->getOutput()) : null;
        }

        return $this->sha;
    }

    /**
     * Migrations on disk with checksums; compared with the installed release to
     * detect edited migrations.
     *
     * @return array<string, string>
     */
    public function migrations(): array
    {
        $files = collect(File::files(database_path('migrations')))
            ->filter(fn ($f) => $f->getExtension() === 'php')
            ->sortBy(fn ($f) => $f->getFilename())
            ->mapWithKeys(fn ($f) => [
                $f->getFilenameWithoutExtension() => hash_file('sha256', $f->getPathname()),
            ]);

        return $files->all();
    }

    public function schemaHash(): string
    {
        return Canonical::hash($this->migrations());
    }

    /** @return array<string, mixed> */
    public function toArray(): array
    {
        $built = $this->built() ?? [];

        return [
            'app_version' => $this->version(),
            'git_sha' => $this->gitSha(),
            'build_id' => $built['build_id'] ?? null,
            'built_at' => $built['built_at'] ?? null,
            'api_contract_version' => config('kitchen.worker.contract_version'),
            'schema_hash' => $this->schemaHash(),
            'migrations' => $this->migrations(),
            'dependency_locks' => $built['dependency_locks'] ?? $this->dependencyLocks(),
            'tagged' => $this->isTagged(),
        ];
    }

    /** @return array<string, string|null> */
    public function dependencyLocks(): array
    {
        return collect(['composer.lock', 'package-lock.json', 'ai-service/requirements.lock'])
            ->mapWithKeys(fn ($f) => [$f => File::exists(base_path($f)) ? hash_file('sha256', base_path($f)) : null])
            ->all();
    }
}
